declare(strict_types=1);require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../_helper.php';uks_require_access($pdo);if(!uks_can_manage($pdo))deny_access();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$kode=trim((string)$_POST['kode']);$nama=trim((string)$_POST['nama']);$satuan=trim((string)$_POST['satuan']);$min=max(0,(int)$_POST['stok_minimum']);$stok=max(0,(int)$_POST['stok_awal']);$lokasi=trim((string)$_POST['lokasi']);$kadaluarsa=trim((string)($_POST['tanggal_kadaluarsa']??''));if($kadaluarsa!=='' && !preg_match('/^\d{4}-\d{2}-\d{2}$/',$kadaluarsa))$kadaluarsa='';if($kode===''||$nama===''||$satuan==='')$error='Kode, nama, dan satuan wajib diisi.';else{try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO uks_obat(kode,nama,satuan,stok_minimum,stok_saat_ini,lokasi,tanggal_kadaluarsa,aktif) VALUES(?,?,?,?,?,?,?,1)");$st->execute([$kode,$nama,$satuan,$min,$stok,$lokasi,$kadaluarsa!==''?$kadaluarsa:null]);$id=(int)$pdo->lastInsertId();if($stok>0)$pdo->prepare("INSERT INTO uks_stok_transaksi(obat_id,jenis,jumlah,stok_sebelum,stok_sesudah,tanggal,user_id,keterangan) VALUES(?,?,?,?,?,?,?,?)")->execute([$id,'masuk',$stok,0,$stok,date('Y-m-d'),user_id(),'Stok awal']);uks_audit($pdo,'CREATE',$id,'Menambah master obat UKS');$pdo->commit();uks_flash('Obat berhasil ditambahkan.');redirect('uks/obat/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Kode obat sudah digunakan.':'Gagal menambah obat.';}}}$page_title='Tambah Obat UKS';require_once __DIR__.'/../../layouts/header.php';require_once __DIR__.'/../../layouts/sidebar.php';?><main class="main uks-module-page"><header class="topbar"><div class="topbar-title">Tambah Obat</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Tambah Obat UKS</h1><p>Masukkan master obat dan stok awal.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Kembali</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="form-card"><div class="form-grid"><div class="form-group"><label>Kode *</label><input class="form-control" name="kode" value="<?=e($_POST['kode']??'')?>" required></div><div class="form-group"><label>Nama Obat *</label><input class="form-control" name="nama" value="<?=e($_POST['nama']??'')?>" required></div><div class="form-group"><label>Satuan *</label><input class="form-control" name="satuan" value="<?=e($_POST['satuan']??'')?>" placeholder="Tablet / botol / tube" required></div><div class="form-group"><label>Stok Minimum</label><input class="form-control" type="number" min="0" name="stok_minimum" value="<?=e($_POST['stok_minimum']??'5')?>"></div><div class="form-group"><label>Stok Awal</label><input class="form-control" type="number" min="0" name="stok_awal" value="<?=e($_POST['stok_awal']??'0')?>"></div><div class="form-group"><label>Lokasi</label><input class="form-control" name="lokasi" value="<?=e($_POST['lokasi']??'')?>" placeholder="Lemari UKS"></div><div class="form-group"><label>Tanggal Kedaluwarsa</label><input class="form-control" type="date" name="tanggal_kadaluarsa" value="<?=e($_POST['tanggal_kadaluarsa']??'')?>"><small class="text-muted">Kosongkan jika belum diketahui.</small></div></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Batal</a></div></form></section></main><?php require_once __DIR__.'/../../layouts/footer.php';
